import { forwardRef, type TextareaHTMLAttributes } from 'react';

export type TextareaProps = {
  error?: boolean;
  className?: string;
} & Omit<TextareaHTMLAttributes<HTMLTextAreaElement>, 'className'>;

function cn(...classes: (string | false | undefined | null)[]) {
  return classes.filter(Boolean).join(' ');
}

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(
  ({ error = false, className, ...props }, ref) => {
    return (
      <textarea
        ref={ref}
        className={cn('textarea', className)}
        aria-invalid={error || undefined}
        {...props}
      />
    );
  },
);

Textarea.displayName = 'Textarea';

/* -------------------------------------------------------------------------
   Textarea

   Multi-line text input. Shares color system with Input.
   Min height 80px, resizable vertically by default.
   Colors matched to Figma atom-text-field.

   States: default, focus, disabled, error
   ------------------------------------------------------------------------- */

.textarea {
  display: flex;
  width: 100%;
  min-height: 5rem;
  padding: var(--spacing-2);
  border: var(--stroke-thin) solid var(--border-input);
  border-radius: var(--radius-md);
  background-color: var(--background);
  color: var(--foreground);
  font-family: var(--font-family-sans), ui-sans-serif, system-ui, sans-serif;
  font-size: var(--font-size-sm);
  line-height: 1.5;
  resize: vertical;
  outline: none;
  transition:
    border-color var(--duration-150) var(--easing-out),
    box-shadow var(--duration-150) var(--easing-out);
}

.textarea::placeholder {
  color: var(--placeholder);
}

.textarea:focus {
  border-color: var(--border-focus);
  box-shadow: 0 0 0 var(--stroke-medium) var(--focus-ring-color);
}

.textarea:disabled {
  background-color: var(--muted);
  border-color: var(--muted);
  color: var(--muted-foreground);
  cursor: not-allowed;
  resize: none;
  opacity: 1;
}

.textarea[aria-invalid="true"] {
  border-color: var(--destructive);
  box-shadow: 0 0 var(--stroke-medium) 0 var(--focus-ring-error-color);
}

.textarea[aria-invalid="true"]:focus {
  border-color: var(--destructive);
  box-shadow: 0 0 0 var(--stroke-medium) var(--focus-ring-error-color);
}

